x=p(); process_refund_request(x,"100.00","u",T0); print("full", x.refunded_amount, x.status)
# over refund
try: process_refund_request(p(),"100.01","u",T0)
except BillingError as e: print("over", e.code)
# non captured
try: process_refund_request(p(status="authorized"),"1.00","u",T0)
except BillingError as e: print("state", e.code)
# non positive
try: process_refund_request(p(),"0","u",T0)
except BillingError as e: print("nonpos", e.code)
# approval
try: process_refund_request(p("1000.00"),"500.01","u",T0)
except BillingError as e: print("approval", e.code)
x=p("1000.00"); process_refund_request(x,"500.00","u",T0); print("at threshold ok", x.refunded_amount)
x=p("1000.00"); process_refund_request(x,"600.00","u",T0,approved_by="mgr"); print("approved ok", x.refunded_amount)
EOF"}

